## Code Example
```javascript
// 3-valued constants
const T = 'T', F = 'F', U = 'U';
function xor3(a,b){
  if(a==='U' || b==='U') return 'U';
  return a===b ? 'F' : 'T';
}
function imp(x,y){
  // Kleene: ¬x is T->F, F->T, U->U; then max with y (T>U>F)
  const not = (v)=> v==='T' ? 'F' : v==='F' ? 'T' : 'U';
  const order = { 'F':0, 'U':1, 'T':2 };
  const nx = not(x);
  return order[nx] >= order[y] ? nx : y;
}
```

